{"file_path":"forth.py","content":"class StackUnderflowError(Exception):
    """Exception raised when the stack does not have enough items.

    message: explanation of the error.
    """

    def __init__(self, message):
        self.message = message
        super().__init__(message)


def _is_number(token):
    try:
        int(token)
        return True
    except ValueError:
        return False


def evaluate(input_data):
    stack = []
    definitions = {}

    for line in input_data:
        tokens = line.split()
        _process(tokens, stack, definitions)

    return stack


def _expand(tokens, definitions):
    expanded = []
    for token in tokens:
        lower = token.lower()
        if lower in definitions:
            expanded.extend(definitions[lower])
        else:
            expanded.append(token)
    return expanded


def _process(tokens, stack, definitions):
    if tokens and tokens[0] == ":":
        if tokens[-1] != ";":
            raise ValueError("illegal operation")
        name = tokens[1]
        if _is_number(name):
            raise ValueError("illegal operation")
        body = tokens[2:-1]
        definitions[name.lower()] = _expand(body, definitions)
        return

    expanded = _expand(tokens, definitions)

    for token in expanded:
        lower = token.lower()
        if _is_number(token):
            stack.append(int(token))
        elif lower == "+":
            _require(stack, 2)
            b, a = stack.pop(), stack.pop()
            stack.append(a + b)
        elif lower == "-":
            _require(stack, 2)
            b, a = stack.pop(), stack.pop()
            stack.append(a - b)
        elif lower == "*":
            _require(stack, 2)
            b, a = stack.pop(), stack.pop()
            stack.append(a * b)
        elif lower == "/":
            _require(stack, 2)
            b, a = stack.pop(), stack.pop()
            if b == 0:
                raise ZeroDivisionError("divide by zero")
            stack.append(int(a / b))
        elif lower == "dup":
            _require(stack, 1)
            stack.append(stack[-1])
        elif lower == "drop":
            _require(stack, 1)
            stack.pop()
        elif lower == "swap":
            _require(stack, 2)
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif lower == "over":
            _require(stack, 2)
            stack.append(stack[-2])
        else:
            raise ValueError("undefined operation")


def _require(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")
